/bin/bash -lc "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
from collections import Counter
class Audit(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=[]; self.labels=[]; self.patterns=[]; self.panels=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a: self.ids.append(a['id'])
        if tag=='label' and 'for' in a: self.labels.append(a['for'])
        if 'pattern' in a: self.patterns.append(a['pattern'])
        if 'data-panel' in a: self.panels.append(a['data-panel'])
a=Audit(); a.feed(Path('index.html').read_text())
assert not [i for i,n in Counter(a.ids).items() if n>1], 'Duplicate IDs'
assert all(i in a.ids for i in a.labels), 'Broken form labels'
assert a.panels==['0','1','2','3'], 'Missing booking steps'
print('HTML checks passed: four steps, unique IDs, linked form labels.')
import json
Path('/tmp/spruce-patterns.json').write_text(json.dumps(a.patterns))
