/bin/bash -lc "node - <<'JS'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
new Function(html.match(/<script>([\\s\\S]*?)<\\/script>/)[1]);
const patterns = [...html.matchAll(/pattern=\"(["'^"]+)"/g)].map(m => new RegExp('"'"'^(?:'"' + m[1] + ')"'$'"', 'v'));
if ("'!patterns[0].test('"'+1 (555) 123-4567') || patterns[0].test('not a phone')) throw new Error('Phone validation failed');
if ("'!patterns[1].test('"'10001') || "'!patterns[1].test('"'10001-1234') || patterns[1].test('123')) throw new Error('ZIP validation failed');
for (const id of ['i-spark','i-arrow','i-left','i-right','i-check','i-shield','i-lock','i-mail','i-phone','i-home','i-calendar','i-leaf','i-chat','i-bed','i-bath','i-heart']) {
  if ("'!html.includes('"'id=\"' + id + '\"')) throw new Error('Missing icon ' + id);
}
console.log('Passed: JavaScript syntax, phone/ZIP valid and invalid cases, inline icon references.');
console.log('Deliverable: index.html (' + (Buffer.byteLength(html) / 1024).toFixed(1) + ' KB)');
JS"

